sparql_query:
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?movie ?movieLabel ?director ?directorLabel
WHERE {
  # Match movies (items that have the director property)
  ?movie ns1:director ?director .

  # Get the label for the movie
  OPTIONAL { ?movie rdfs:label ?movieLabel }

  # Get the label for the director
  OPTIONAL { ?director rdfs:label ?directorLabel }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?location
WHERE {
  {
    ?location a ?type .
    ?type rdfs:subClassOf* <http://www.w3.org/2002/07/owl#Thing> .
    FILTER(
      CONTAINS(LCASE(STR(?location)), "city") || 
      CONTAINS(LCASE(STR(?location)), "town") || 
      CONTAINS(LCASE(STR(?location)), "country") || 
      CONTAINS(LCASE(STR(?location)), "island") || 
      CONTAINS(LCASE(STR(?location)), "continent") || 
      CONTAINS(LCASE(STR(?location)), "ocean") || 
      CONTAINS(LCASE(STR(?location)), "mountain") || 
      CONTAINS(LCASE(STR(?location)), "base") || 
      CONTAINS(LCASE(STR(?location)), "realm") || 
      CONTAINS(LCASE(STR(?location)), "dimension")
    )
  }
  UNION
  {
    ?location ns1:placeofbirth ?birthplace .
  }
  UNION
  {
    ?location ns1:baseofoperations ?base .
  }
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?location
WHERE {
  ?location rdf:type <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/location> .
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?movie ?movieLabel ?director ?directorLabel
WHERE {
  ?movie a <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/movie> .
  {
    ?director ns1:directed ?movie .
  } UNION {
    ?movie ns1:director ?director .
  }
  OPTIONAL { ?movie rdfs:label ?movieLabel . }
  OPTIONAL { ?director rdfs:label ?directorLabel . }
}
ORDER BY LCASE(STR(?movieLabel)) LCASE(STR(?directorLabel))

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>

SELECT DISTINCT ?character ?characterLabel ?realName ?alias
WHERE {
  ?character a <http://dbkwik.webdatacommons.org/marvel.wikia.com/class/character> .
  OPTIONAL { ?character rdfs:label ?characterLabel . }
  OPTIONAL { ?character ns1:realname ?realName . }
  OPTIONAL { ?character skos:altLabel ?alias . }
}
ORDER BY LCASE(STR(?characterLabel)) ?character

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>

SELECT DISTINCT ?character ?characterLabel ?realName ?alias
WHERE {
  {
    ?character rdf:type <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/character> .
  } UNION {
    ?character (ns1:realName|ns1:alias) ?_x .
  }
  OPTIONAL { ?character rdfs:label ?characterLabel . }
  OPTIONAL {
    ?character ns1:realName ?rn .
    OPTIONAL { ?rn rdfs:label ?rnLabel . }
    BIND(COALESCE(?rnLabel, STR(?rn)) AS ?realName)
  }
  OPTIONAL {
    ?character ns1:alias ?al .
    OPTIONAL { ?al rdfs:label ?alLabel . }
    BIND(COALESCE(?alLabel, STR(?al)) AS ?alias)
  }
}
ORDER BY LCASE(STR(?characterLabel)) ?character

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?movieLabel ?releaseDate ?year
WHERE {
  {
    ?movie a <http://dbkwik.webdatacommons.org/marvel.wikia.com/class/youtube> .
  }
  UNION
  {
    ?movie a <http://dbkwik.webdatacommons.org/marvel.wikia.com/class/imdb_title> .
  }

  ?movie rdfs:label ?movieLabel .
  OPTIONAL { ?movie ns1:releasedate ?releaseDate . }
  OPTIONAL { ?movie ns1:year ?year . }
}

PREFIX ns3: <http://dbkwik.webdatacommons.org/ontology/>
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?movieLabel ?releaseDate
WHERE {
  ?movie a ns3:Movie .
  ?movie rdfs:label ?movieLabel .
  OPTIONAL {
    ?movie (ns1:release | ns1:released) ?releaseDate .
  }
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>

SELECT DISTINCT ?media
WHERE {
  { ?s ns1:movies ?media . }
  UNION
  { ?s ns1:television ?media . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?media ?label
WHERE {
  VALUES ?mediaType {
    <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/movie>
    <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/tv>
    <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/web_series>
    <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/documentary>
  }
  ?media rdf:type ?mediaType .
  ?media rdfs:label ?label .
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>

SELECT DISTINCT ?character ?species
WHERE {
  ?character ns1:species ?species .
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?character ?characterLabel ?species ?speciesLabel
WHERE {
  ?character ns1:species ?species .
  OPTIONAL { ?character rdfs:label ?characterLabel . }
  OPTIONAL { ?species   rdfs:label ?speciesLabel . }
}
ORDER BY ?characterLabel

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>

SELECT DISTINCT ?character ?origin
WHERE {
  { ?character ns1:origin ?origin }
  UNION
  { ?character ns1:placeofbirth ?origin }
  UNION
  { ?character ns1:baseofoperations ?origin }
}
ORDER BY ?character

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>

SELECT DISTINCT ?character ?originLocation
WHERE {
  VALUES ?originProp { ns1:homeplanet ns1:birthplace ns1:base }
  ?character ?originProp ?originLocation .
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?character ?movie
WHERE {
  ?character ns1:movies ?movie .
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?character ?movie
WHERE {
  ?character ns1:movie ?movie .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>

SELECT DISTINCT ?location ?label
WHERE {
  ?char a <http://dbkwik.webdatacommons.org/marvel.wikia.com/class/character> ;
        (ns1:placeofbirth|ns1:baseofoperations) ?location .
  FILTER(isIRI(?location))
  OPTIONAL { ?location rdfs:label ?label . }
}
ORDER BY ?label ?location

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>

SELECT DISTINCT ?loc ?locLabel WHERE {
  {
    { ?char rdf:type <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/character> }
    UNION
    { ?char ns1:actor ?actor }
    { ?char ns1:citizenship ?loc }
    UNION
    { ?char ns1:homeplanet ?loc }
  }
  UNION
  {
    { ?char rdf:type <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/character> }
    UNION
    { ?char ns1:actor ?actor }
    ?char ?charWorkProp ?work .
    FILTER(?charWorkProp IN (ns1:movie, ns1:tvSeries))
    ?loc rdf:type <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/location> ;
         ?locWorkProp ?work .
    FILTER(?locWorkProp IN (ns1:movie, ns1:tvSeries))
  }
  OPTIONAL { ?loc rdfs:label ?locLabel }
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>

SELECT ?character ?team ?movie
WHERE {
  ?character ns1:teams ?team .
  ?character ns1:movies ?movie .
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>
PREFIX class: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/>

SELECT ?character ?team ?movie
WHERE {
    ?character a class:character .
    ?team a class:organization .
    ?movie a class:movie .

    ?character ns1:movie ?movie .

    { ?team ns1:members ?character . } 
    UNION 
    { ?team ns1:formermembers ?character . } 
    UNION 
    { ?team ns1:leader ?character . }
    UNION 
    { ?team ns1:founder ?character . }
    UNION
    { ?character ns1:team ?team . }
    UNION
    { ?character ns1:affiliation ?team . }
}

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>

SELECT DISTINCT ?movie ?team
WHERE {
  ?character ns1:movies ?movie .
  ?character ns1:teams ?team .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>
PREFIX ns2: <http://dbkwik.webdatacommons.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?character ?powerCount ?popularity
WHERE {
  ?pg rdf:type <http://dbkwik.webdatacommons.org/marvel.wikia.com/class/official_power_grid> ;
      rdfs:label ?pgLabel .
  BIND(STRBEFORE(STR(?pgLabel), "/Power Grid") AS ?character)

  {
    SELECT ?pg (COUNT(?val) AS ?powerCount)
    WHERE {
      ?pg rdf:type <http://dbkwik.webdatacommons.org/marvel.wikia.com/class/official_power_grid> .
      VALUES ?prop { ns1:durability ns1:energyProjection ns1:fightingSkills ns1:intelligence ns1:speed ns1:strength }
      ?pg ?prop ?val .
    }
    GROUP BY ?pg
  }

  OPTIONAL {
    {
      SELECT ?character (COUNT(DISTINCT ?src) AS ?popularity)
      WHERE {
        ?char rdfs:label ?charLabel .
        BIND(STR(?charLabel) AS ?character)
        ?src ns2:wikiPageWikiLink ?char .
      }
      GROUP BY ?character
    }
  }
}
ORDER BY DESC(?popularity) DESC(?powerCount) ?character

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?movie ?movieLabel
       (COUNT(DISTINCT ?team) AS ?uniqueTeams)
       (COUNT(DISTINCT ?power) AS ?uniquePowers)
       (COUNT(DISTINCT ?loc) AS ?uniqueLocations)
WHERE {
  ?char ns1:movies ?movie .
  OPTIONAL { ?movie rdfs:label ?movieLabel . }

  OPTIONAL {
    { ?char ns1:teams ?team . }
    UNION
    { ?char ns1:teames ?team . }
  }

  OPTIONAL { ?char ns1:powers ?power . }

  OPTIONAL {
    { ?char ns1:baseofoperations ?loc . }
    UNION
    { ?char ns1:placeofbirth ?loc . }
    UNION
    { ?char ns1:origin ?loc . }
  }
}
GROUP BY ?movie ?movieLabel
ORDER BY ?movie

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>

SELECT ?movie
       (COUNT(DISTINCT ?team) AS ?uniqueTeams)
       (COUNT(DISTINCT ?power) AS ?uniquePowers)
       (COUNT(DISTINCT ?loc) AS ?uniqueLocations)
WHERE {
  ?char ns1:movie ?movie .
  OPTIONAL { ?char (ns1:team|ns1:affiliation) ?team . }
  OPTIONAL { ?char ns1:species ?power . }
  OPTIONAL { ?char (ns1:citizenship|ns1:homeplanet|ns1:location) ?loc . }
}
GROUP BY ?movie

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvel.wikia.com/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?location (COUNT(?subject) AS ?associationCount)
WHERE {
    { ?subject ns1:placeofbirth ?location . }
    UNION
    { ?subject ns1:baseofoperations ?location . }
    UNION
    { ?subject ns1:historytext ?location . }
}
GROUP BY ?location
HAVING (COUNT(?subject) > 1)
ORDER BY DESC(?associationCount)

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?location (COUNT(DISTINCT ?association) AS ?associationCount)
WHERE {
  {
    ?entity (ns1:location|ns1:locations|ns1:place|ns1:headquarters|ns1:homeplanet|ns1:citizenship|ns1:continent) ?location .
    {
      BIND(?entity AS ?association)
      ?association a ?type .
      FILTER(?type IN (<http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/character>, <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/movie>))
    }
    UNION
    {
      ?entity (ns1:movie|ns1:character|ns1:members|ns1:formermembers|ns1:actor|ns1:participants|ns1:inhabitants|ns1:owner|ns1:users|ns1:leader|ns1:founder|ns1:pilot|ns1:passengers|ns1:performer|ns1:voiceActor|ns1:film|ns1:movies|ns1:tvSeries|ns1:oneShot) ?association .
      ?association a ?type .
      FILTER(?type IN (<http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/character>, <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/movie>))
    }
  }
  UNION
  {
    ?location (ns1:movie|ns1:character|ns1:members|ns1:formermembers|ns1:actor|ns1:participants|ns1:inhabitants|ns1:owner|ns1:users|ns1:leader|ns1:founder|ns1:pilot|ns1:passengers|ns1:performer|ns1:voiceActor|ns1:film|ns1:movies|ns1:tvSeries|ns1:oneShot) ?association .
    ?association a ?type .
    FILTER(?type IN (<http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/character>, <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/class/movie>))
  }

  FILTER(isURI(?location))
}
GROUP BY ?location
HAVING (COUNT(DISTINCT ?association) > 1)
ORDER BY DESC(?associationCount)

PREFIX ns1: <http://dbkwik.webdatacommons.org/marvelcinematicuniverse.wikia.com/property/>

SELECT ?team (GROUP_CONCAT(DISTINCT ?movie; SEPARATOR=", ") AS ?movies)
WHERE {
  { ?team ns1:members      ?member } UNION
  { ?team ns1:formermembers ?member }
  ?member ns1:movie ?movie .
}
GROUP BY ?team
